// Cenarios de teste da ponte. Cada item vira um POST no webhook de producao.
// O texto da mensagem controla o comportamento do stub de CRM.
const agora = new Date().toISOString();
const marca = Date.now();

const valido = {
  canal: 'instagram',
  id_evento: 'IG-TESTE-' + marca,
  remetente: '@cliente_teste',
  texto: 'Ola, quero um orcamento para Porto em julho',
  timestamp: agora,
};

return [
  { json: { cenario: '01 - evento valido', esperado: 'entregue', payload: valido } },
  { json: { cenario: '02 - evento duplicado', esperado: 'duplicado', payload: valido } },
  { json: { cenario: '03 - campos obrigatorios ausentes', esperado: 'invalido', payload: { canal: 'instagram', id_evento: 'IG-TESTE-' + marca + '-3', remetente: '', texto: '' } } },
  { json: { cenario: '04 - falha transitoria com retry', esperado: 'entregue na 3a tentativa', payload: { canal: 'whatsapp', id_evento: 'WA-TESTE-' + marca + '-4', remetente: '+55 11 90000-0004', texto: 'FALHA_TRANSITORIA orcamento para Maragogi', timestamp: agora } } },
  { json: { cenario: '05 - falha permanente 4xx', esperado: 'invalido, sem retry', payload: { canal: 'whatsapp', id_evento: 'WA-TESTE-' + marca + '-5', remetente: '+55 11 90000-0005', texto: 'FALHA_PERMANENTE payload rejeitado pelo CRM', timestamp: agora } } },
  { json: { cenario: '06 - CRM fora do ar (esgota o retry)', esperado: 'falha + fila de reprocessamento + alerta', payload: { canal: 'instagram', id_evento: 'IG-TESTE-' + marca + '-6', remetente: '@cliente_teste_6', texto: 'FALHA_SEMPRE quero um orcamento', timestamp: agora } } },
];

// Junta o que foi enviado com o que a ponte respondeu.
const enviados = $('Cenarios de teste').all();
const linhas = $input.all().map((item, i) => ({
  cenario: enviados[i] ? enviados[i].json.cenario : 'desconhecido',
  esperado: enviados[i] ? enviados[i].json.esperado : null,
  http_da_ponte: item.json.statusCode,
  resposta_da_ponte: item.json.body,
}));

return [{ json: { total: linhas.length, executado_em: new Date().toISOString(), resultados: linhas } }];
